using Lumi.Bytecode;
using Lumi.Bytecode.Constants;
using Lumi.Bytecode.Instructions;
using Lumi.VM.BinaryInstructions;

namespace Lumi.VM;

/// <summary>
/// Represents a simple stack-based virtual machine capable of executing bytecode instructions generated by a compiler
/// or bytecode generator.
/// </summary>
public sealed class VirtualMachine
{
    private readonly Stack _stack;
    private IReadOnlyList<Instruction> _instructions;
    private IReadOnlyList<Constant> _constants;
    private int _ip;
    private int _executedInstructionCount;

    public VirtualMachine()
    {
        _stack = new Stack();
        _instructions = [];
        _constants = [];
        _ip = 0;
        _executedInstructionCount = 0;
    }

    /// <summary>
    /// Executes the provided bytecode by interpreting its instructions sequentially.
    /// </summary>
    /// <param name="bytecode">The bytecode to execute, containing the instructions and constants to be processed.</param>
    public void Execute(BytecodeResult bytecode)
    {
        _instructions = bytecode.Instructions;
        _constants = bytecode.Constants;

        // Start execution from where we left off, not from the beginning
        _ip = _executedInstructionCount;

        while (_ip < _instructions.Count)
        {
            switch (_instructions[_ip].Kind)
            {
                case InstructionKind.PushConst:
                    PushConst();
                    break;
                case InstructionKind.Add:
                    new BinaryInstruction(_stack).Add();
                    break;
                case InstructionKind.Sub:
                    new BinaryInstruction(_stack).Sub();
                    break;
                case InstructionKind.Mul:
                    new BinaryInstruction(_stack).Mul();
                    break;
                case InstructionKind.Div:
                    new BinaryInstruction(_stack).Div();
                    break;
                case InstructionKind.Print:
                    Print();
                    break;
            }

            _ip += 1;
        }

        // Track how many instructions we've executed for the next call
        _executedInstructionCount = _ip;
    }

    private void PushConst()
    {
        var pushConst = _instructions[_ip].SafeGetIntOperand();
        var constant = _constants[pushConst];

        _stack.Push(Value.ConstantToValue(constant));
    }

    private void Print()
    {
        var value = _stack.Peek();
        Console.WriteLine(value.PrintValue());
    }
}